function saveExecutionReport(reportInput) {
  const report = normalizeExecutionReport(reportInput);
  const transaction = db.transaction(() => {
    db.prepare(
      `
        INSERT INTO reports (
          id,
          suite_id,
          suite_name,
          environment,
          start_time,
          end_time,
          status,
          pass_rate,
          total_cases,
          passed_cases,
          failed_cases
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          suite_id = excluded.suite_id,
          suite_name = excluded.suite_name,
          environment = excluded.environment,
          start_time = excluded.start_time,
          end_time = excluded.end_time,
          status = excluded.status,
          pass_rate = excluded.pass_rate,
          total_cases = excluded.total_cases,
          passed_cases = excluded.passed_cases,
          failed_cases = excluded.failed_cases
      `
    ).run(
      report.id,
      report.suiteId,
      nullableText(report.suiteName),
      nullableText(report.environment),
      report.startTime,
      report.endTime ?? null,
      report.status,
      report.passRate,
      report.totalCases ?? null,
      report.passedCases ?? null,
      report.failedCases ?? null
    );
    db.prepare("DELETE FROM report_logs WHERE report_id = ?").run(report.id);
    for (const [index2, log] of report.logs.entries()) {
      db.prepare(
        `
          INSERT INTO report_logs (report_id, step_id, timestamp, status, level, message, screenshot, metadata, position)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `
      ).run(
        report.id,
        log.stepId,
        log.timestamp,
        log.status,
        log.level || "info",
        log.message,
        nullableText(log.screenshot),
        log.metadata ? JSON.stringify(log.metadata) : null,
        index2
      );
    }
  });
  transaction();
  return getExecutionReport(report.id) || report;
}
